async def act(page):
    """Update order #301 shipping address to:
      321 Birch Boulevard
      Suite 200
      Dallas, TX 75201

    This coroutine performs the UI interactions to open the order and update the
    shipping address using accessibility-role-centric selectors and conservative
    locator.count() checks.
    """

    street_lines = ["321 Birch Boulevard", "Suite 200"]
    city = "Dallas"
    region = "TX"
    postcode = "75201"
    country_label = "United States"

    # 1) Navigate to Sales > Orders grid (deterministic relative path)
    await page.goto('/index.php/admin/sales_order/')
    await page.wait_for_timeout(1000)

    # 2) Locate and open order 301
    opened = False
    order_link = page.get_by_role('link', name='301')
    if await order_link.count() > 0:
        await order_link.first.click()
        await page.wait_for_load_state('networkidle')
        opened = True

    if not opened:
        tables = page.get_by_role('table')
        tbl_count = await tables.count()
        for i in range(tbl_count):
            tbl = tables.nth(i)
            # rows that contain the text '301'
            rows = tbl.get_by_role('row').filter(has=page.get_by_text('301'))
            if await rows.count() > 0:
                row = rows.first
                links_in_row = row.get_by_role('link')
                if await links_in_row.count() > 0:
                    await links_in_row.first.click()
                    await page.wait_for_load_state('networkidle')
                    opened = True
                    break
                else:
                    # try clicking the row itself
                    try:
                        await row.click()
                        await page.wait_for_load_state('networkidle')
                        opened = True
                        break
                    except Exception:
                        pass
        # final fallback: any visible text node
    if not opened:
        txts = page.get_by_text('301')
        if await txts.count() > 0:
            await txts.first.click()
            await page.wait_for_load_state('networkidle')
            opened = True

    if not opened:
        raise RuntimeError('Unable to locate or open order 301 from the Orders grid')

    # 3) Wait for order details to stabilize
    await page.wait_for_timeout(800)

    # 4) Locate Shipping Address label/group
    shipping_label = page.get_by_text('Shipping Address')
    if await shipping_label.count() == 0:
        shipping_label = page.get_by_text('Ship to')

    # 5) Click a scoped 'Change' or 'Edit' control near Shipping Address
    clicked_edit = False
    if await shipping_label.count() > 0:
        shipping_groups = page.get_by_role('group').filter(has=shipping_label.first)
        if await shipping_groups.count() > 0:
            grp = shipping_groups.first
            change_links = grp.get_by_role('link', name='Change')
            if await change_links.count() > 0:
                await change_links.first.click()
                clicked_edit = True
            else:
                edit_links = grp.get_by_role('link', name='Edit')
                if await edit_links.count() > 0:
                    await edit_links.first.click()
                    clicked_edit = True
                else:
                    edit_btns = grp.get_by_role('button', name='Edit')
                    if await edit_btns.count() > 0:
                        await edit_btns.first.click()
                        clicked_edit = True

    # fallback to page-level controls
    if not clicked_edit:
        if await page.get_by_role('link', name='Change').count() > 0:
            await page.get_by_role('link', name='Change').first.click()
            clicked_edit = True
        elif await page.get_by_role('link', name='Edit').count() > 0:
            await page.get_by_role('link', name='Edit').first.click()
            clicked_edit = True
        elif await page.get_by_role('button', name='Edit').count() > 0:
            await page.get_by_role('button', name='Edit').first.click()
            clicked_edit = True

    await page.wait_for_timeout(800)

    # 6) Fill address fields scoped to the shipping group if available
    filled_any = False
    if await shipping_label.count() > 0:
        shipping_groups = page.get_by_role('group').filter(has=shipping_label.first)
        if await shipping_groups.count() > 0:
            grp = shipping_groups.first
            tboxes = grp.get_by_role('textbox')
            tb_count = await tboxes.count()
            if tb_count > 0:
                try:
                    await tboxes.nth(0).fill(street_lines[0] + '\n' + street_lines[1])
                    filled_any = True
                except Exception:
                    pass
            if tb_count > 1:
                try:
                    await tboxes.nth(1).fill(city)
                    filled_any = True
                except Exception:
                    pass
            if tb_count > 2:
                try:
                    await tboxes.nth(2).fill(region)
                    filled_any = True
                except Exception:
                    pass
            if tb_count > 3:
                try:
                    await tboxes.nth(3).fill(postcode)
                    filled_any = True
                except Exception:
                    pass

    # 7) Fallback: try labeled textboxes or first textboxes on page
    if not filled_any:
        field_attempts = [
            (('Street Address', 'Street', 'Street 1', 'Street 2'), street_lines[0] + '\n' + street_lines[1]),
            (('City', 'Town/City', 'city'), city),
            (('State/Province', 'State', 'Region'), region),
            (('Zip/Postal Code', 'Zip', 'Postal Code', 'Postcode'), postcode),
        ]
        for names, value in field_attempts:
            for nm in names:
                try:
                    tb = page.get_by_role('textbox', name=nm)
                    if await tb.count() > 0:
                        await tb.first.fill(value)
                        break
                except Exception:
                    pass
        # final fallback
        all_tboxes = page.get_by_role('textbox')
        total = await all_tboxes.count()
        if total > 0:
            try:
                await all_tboxes.nth(0).fill(street_lines[0] + '\n' + street_lines[1])
            except Exception:
                pass
        if total > 1:
            try:
                await all_tboxes.nth(1).fill(city)
            except Exception:
                pass
        if total > 2:
            try:
                await all_tboxes.nth(2).fill(region)
            except Exception:
                pass
        if total > 3:
            try:
                await all_tboxes.nth(3).fill(postcode)
            except Exception:
                pass

    # 8) Select Country (prefer scoped combobox)
    country_selected = False
    if await shipping_label.count() > 0:
        shipping_groups = page.get_by_role('group').filter(has=shipping_label.first)
        if await shipping_groups.count() > 0:
            grp = shipping_groups.first
            cb = grp.get_by_role('combobox', name='Country')
            if await cb.count() > 0:
                try:
                    await cb.first.select_option(label=country_label)
                    country_selected = True
                except Exception:
                    country_selected = False
    if not country_selected:
        comboboxes = page.get_by_role('combobox')
        cb_count = await comboboxes.count()
        for i in range(cb_count):
            cb = comboboxes.nth(i)
            try:
                await cb.select_option(label=country_label)
                country_selected = True
                break
            except Exception:
                pass

    # 9) Click Save/Update scoped to the shipping group; fallback to page-level
    saved = False
    save_names = ('Save Address', 'Save', 'Update', 'Submit', 'OK')
    if await shipping_label.count() > 0:
        shipping_groups = page.get_by_role('group').filter(has=shipping_label.first)
        if await shipping_groups.count() > 0:
            grp = shipping_groups.first
            for nm in save_names:
                btns = grp.get_by_role('button', name=nm)
                if await btns.count() > 0:
                    await btns.first.click()
                    saved = True
                    break
                links = grp.get_by_role('link', name=nm)
                if await links.count() > 0:
                    await links.first.click()
                    saved = True
                    break

    if not saved:
        for nm in save_names:
            btns = page.get_by_role('button', name=nm)
            if await btns.count() > 0:
                await btns.first.click()
                saved = True
                break
            links = page.get_by_role('link', name=nm)
            if await links.count() > 0:
                await links.first.click()
                saved = True
                break

    # 10) Allow any save processing to finish
    await page.wait_for_timeout(1000)

    return

